Perfectoo. Aquí está el programa completo:

```c
#include <stdio.h>

#define M 2   /* filas de A y de C    */
#define K 3   /* columnas de A = filas de B */
#define N 2   /* columnas de B y de C */

int main(void) {
    int A[M][K], B[K][N], C[M][N];

    /* --- Lectura de A --- */
    printf("Matriz A (%d×%d):\n", M, K);
    for (int i = 0; i < M; i++)
        for (int k = 0; k < K; k++) {
            printf("A[%d][%d]: ", i, k);
            scanf("%d", &A[i][k]);
        }

    /* --- Lectura de B --- */
    printf("Matriz B (%d×%d):\n", K, N);
    for (int k = 0; k < K; k++)
        for (int j = 0; j < N; j++) {
            printf("B[%d][%d]: ", k, j);
            scanf("%d", &B[k][j]);
        }

    /* --- Multiplicación: tres ciclos anidados --- */
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            C[i][j] = 0;                    /* INIT antes del ciclo k */
            for (int k = 0; k < K; k++) {
                C[i][j] += A[i][k] * B[k][j];  /* acumulación */
            }
        }
    }

    /* --- Imprimir C --- */
    printf("\nResultado C = A×B (%d×%d):\n", M, N);
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++)
            printf("%6d", C[i][j]);
        printf("\n");
    }

    return 0;
}
```

Regla de oro: `C[i][j] = 0` va ANTES del ciclo `k`, no dentro. Si lo pones dentro, cada vuelta de `k` borra lo acumulado y solo conservas el último producto.

